import { lazy, Suspense, useState } from "react";

export function SettingsRoute({ userId }: { userId: string }) {
  const [open, setOpen] = useState(false);

  // re-created on every render of SettingsRoute
  const Panel = lazy(() => import("./SettingsPanel"));

  return (
    <section>
      <button onClick={() => setOpen(true)}>Open settings</button>
      {open && (
        <Suspense>
          <Panel userId={userId} />
        </Suspense>
      )}
    </section>
  );
}
